def project(y,b):
    y=np.array(y,dtype=float); z=np.maximum(y,0)
    if sum(z)<=b:return z
    lo,hi=0.,max(z)
    for _ in range(80):
        mid=(lo+hi)/2
        if sum(np.maximum(y-mid,0))>b:lo=mid
        else:hi=mid
    return np.maximum(y-hi,0)
def iterate(r,b,eta):
    r=np.array(r,dtype=float); u=np.zeros(2); rows=[]
    for k in range(19):
        rows.append((k,u.copy(),np.sum((u-r)**2)/2))
        u=project(u-eta*(u-r),b)
    return rows
rows=iterate([2,1],2,.5)
for k,u,f in rows[:4]:print('默认迭代:',k,u,f)
print('末点:',rows[-1])
print('步长边界:',iterate([1,1],4,2)[:4])
print('错误只截非负:',np.maximum([1.5,.75],0),'正确投影:',project([1.5,.75],2))
